components/ProductList.tsx#ListProps.typeText:
interface ListProps<T extends Entity> {
  items: T[];
  render: (item: T) => ReactNode;
  empty?: ReactNode;
}

components/ui/Button.tsx#ButtonProps.typeText:
interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "primary" | "ghost";
  size?: "sm" | "md";
}

hooks/useCart.tsx#CartState.typeText:
interface CartState {
  items: CartItem[];
  add: (item: CartItem) => void;
  remove: (id: string) => void;
  total: number;
}

lib/types.ts#Entity.typeText:
interface Entity {
  id: string;
  createdAt: string;
}

lib/types.ts#Product.typeText:
interface Product extends Entity {
  name: string;
  price: number;
  category: Category;
  description: string;
  rating: number;
}

lib/types.ts#Review.typeText:
interface Review extends Entity {
  productId: string;
  author: string;
  stars: 1 | 2 | 3 | 4 | 5;
  text: string;
}

lib/types.ts#CartItem.typeText:
interface CartItem extends Pick<Product, "id" | "name" | "price"> {
  quantity: number;
}

lib/types.ts#Paginated.typeText:
interface Paginated<T extends Entity = Product> {
  items: T[];
  page: number;
  total: number;
}
